// 02-91_lessons-first.cjs - generated by zemory hook guard (plan/27). Settings: policy.json.
"use strict";
const fs = require("node:fs");
const path = require("node:path");

const BT = String.fromCharCode(96);
const relOf = (root, abs) => path.relative(root, path.resolve(root, abs)).replace(/\\/g, "/");
const inside = (rel) => rel && !rel.startsWith("..") && !path.isAbsolute(rel);

// What the call ADDS and REMOVES for a file tool; newLines = added lines not already present (multiset, trimmed).
function edit(payload, root) {
  const tool = payload.tool_name || "";
  const ti = payload.tool_input || {};
  const abs = ti.file_path || ti.notebook_path || "";
  if (!abs || !["Write", "Edit", "MultiEdit", "NotebookEdit"].includes(tool)) return null;
  const rel = relOf(root, abs);
  if (!inside(rel)) return null;
  let added = "", removed = "", exists = false;
  try { exists = fs.existsSync(abs); } catch { exists = false; }
  if (tool === "Write") {
    added = String(ti.content || "");
    try { removed = exists ? fs.readFileSync(abs, "utf8") : ""; } catch { removed = ""; }
  } else if (tool === "Edit") {
    added = String(ti.new_string || ""); removed = String(ti.old_string || "");
  } else if (tool === "MultiEdit") {
    for (const e of ti.edits || []) { added += "\n" + (e.new_string || ""); removed += "\n" + (e.old_string || ""); }
  } else {
    added = String(ti.new_source || "");
  }
  const seen = new Map();
  for (const l of removed.split(/\r?\n/)) { const k = l.trim(); if (k) seen.set(k, (seen.get(k) || 0) + 1); }
  const newLines = [];
  for (const l of added.split(/\r?\n/)) {
    const k = l.trim();
    if (!k) continue;
    const n = seen.get(k) || 0;
    if (n > 0) seen.set(k, n - 1); else newLines.push(l);
  }
  return { tool, abs, rel, added, removed, exists, newLines };
}

// The rule's own text, capped. Folder harness (plan/28 §0d): the body of the rule's header file beside this hook. File harness: the line
// carrying its number in the rules file plus its continuation lines.
function ownRule(root) {
  try {
    // the header file is named after the rule folder (plan/28 §0p); an older copy still has RULE.md
    const own = path.join(__dirname, path.basename(__dirname) + ".md");
    const file = fs.existsSync(own) ? own : path.join(__dirname, "RULE.md");
    let lines = fs.readFileSync(file, "utf8").split(/\r?\n/);
    if (lines[0] === "---") lines = lines.slice(lines.indexOf("---", 1) + 1);
    // a bilingual law (plan/29 §11): English first, the Vietnamese half under "## Luật là gì" - the block quotes the English
    const vi = lines.findIndex((l) => /^##\s+Luật là gì\s*$/.test(l));
    if (vi > 0) lines = lines.slice(0, vi);
    const body = lines.filter((l, i) => i > 0 || l.trim()).slice(0, 30).map((l) => (l.length > 400 ? l.slice(0, 400) + "…" : l));
    return { rel: path.relative(root, file).replace(/\\/g, "/"), text: body.join("\n").trim() };
  } catch {
    return null;
  }
}
function ruleText(root, file, id) {
  try {
    const lines = fs.readFileSync(path.join(root, file), "utf8").split(/\r?\n/);
    const at = lines.findIndex((l) => l.includes(BT + id + BT) || l.startsWith(id + " "));
    if (at < 0) return "";
    const out = [lines[at]];
    for (let i = at + 1; i < lines.length && out.length < 12; i++) {
      const l = lines[i];
      if (!l.trim() || /^(- |#|\x60\x60\x60|\d{2}-\d+ |<!--)/.test(l)) break;
      out.push(l);
    }
    return out.map((l) => (l.length > 400 ? l.slice(0, 400) + "…" : l)).join("\n");
  } catch {
    return "";
  }
}
// The citation: a hook inside a renamed rule folder (plan/28 §0o) cites the folder's full name, which is always the rule's
// current name; a legacy folder or the file harness keeps "rule <id>".
function citation(id) {
  const folder = path.basename(__dirname);
  return /^(Rule|Cons)_(Gate|Keys|Core)_\d+_/.test(folder) ? folder : "rule " + id;
}
function blocked(root, policy, id, what) {
  const own = ownRule(root);
  if (own && own.text) return "BLOCKED (guard layer 1): " + citation(id) + " - " + what + "\n\nThe rule (" + own.rel + "):\n" + own.text;
  const text = ruleText(root, policy.rules_file || "", id);
  return "BLOCKED (guard layer 1): rule " + id + " - " + what + (text ? "\n\nThe rule (" + policy.rules_file + "):\n" + text : "");
}

// A DOOR reminder for a rule that cannot be forbidden, only recalled at the right moment: the FIRST matching call of a
// session is blocked with the rule; the same call retried passes. Remembered per session in <hooks>/.seen.json (git-ignored,
// last 50 sessions). No session id to remember by => never block (fail-open).
function remindOnce(payload, root, policy, key) {
  const sid = String(payload.session_id || payload.transcript_path || "");
  if (!sid) return false;
  const file = path.join(root, policy.flags_dir || "docs/hooks", ".seen.json");
  let all = {};
  try { all = JSON.parse(fs.readFileSync(file, "utf8")) || {}; } catch { all = {}; }
  const list = Array.isArray(all[sid]) ? all[sid] : [];
  if (list.includes(key)) return false;
  all[sid] = list.concat(key);
  const keys = Object.keys(all);
  for (const k of keys.slice(0, Math.max(0, keys.length - 50))) delete all[k];
  try { fs.writeFileSync(file, JSON.stringify(all)); } catch { return false; }
  return true;
}
const ONCE = "\nThis is a reminder, shown once per session: retry the same call to continue.";

// Paths the language rules do not reach: other people's code, frozen hand-overs, deliberate ASCII samples.
// The write-docx reference samples sit under .claude/skills/ in a repo and under _Store/04_SKILLS/ in the parts store.
// The skill's folder is its old name, its host name (doc-write-docx) or its store name (Skill_Doc_WriteDocx, with the
// assembled host build under Claude/<name>/), and the samples folder is references/ (Agent Skills) or the old reference/.
const LANG_EXEMPT = [/(^|\/)external\//, /(^|\/)attic\//, /(^|\/)(skills|03_SKILLS|04_SKILLS)\/[^/]*(write-docx|WriteDocx)[^/]*\/(Claude\/[^/]+\/)?references?\//];
const CODE_EXT = /\.(ts|tsx|js|jsx|mjs|cjs|py)$/i;

const FIX = /(sửa lỗi|sua loi|\bfix(?:ed|es)?\b|\bbug\b|sự cố|su co|\bincident\b|\bregression\b|hồi quy|hoi quy)/i;
// a fix written as "fault ⇒ what was done" (DW pilot 28/10: "Làn POS hở 16 phút ⇒ khoá theo từng dim" named no fix word):
// one line holding a fault word and the arrow
const FAULT = /(?:^|[^\p{L}])(?:lỗi|hỏng|gãy|chết|mất|lệch|thiếu|sót|trễ|đỏ|hở|kẹt|treo|tụt|thừa|sai|deadlock|timeout|Msg\s*\d{3,5})(?![\p{L}])/iu;
const faultArrow = (text) => text.split("\n").some((l) => l.includes("⇒") && FAULT.test(l));
// L-<n>, padded or not (L-7 · L-007); a ledger kept before the frame numbered L<nnn> (DW: L001…L010, cited in commits)
const MARK = /\bL-?\d+\b|không có bài học\s*:|khong co bai hoc\s*:|không bài học\s*:|no lesson\s*:/i;
const LEDGER = /(^|\/)(0[56]_CHANGES|CHANGELOG)\.md$/i;
function hasLedger(root) {
  const base = path.join(root, "docs", "agent", "01_LAW", "_Cons");
  let codes = [];
  try { codes = fs.readdirSync(base); } catch { return false; }
  for (const c of codes) {
    try { if (fs.readdirSync(path.join(base, c)).some((d) => /_LessonsLedger$/.test(d))) return true; } catch { /* not a folder */ }
  }
  return false;
}
function check(payload, root, policy) {
  try {
    const e = edit(payload, root);
    if (!e || !LEDGER.test(e.rel) || !hasLedger(root)) return null;
    const text = e.newLines.join("\n");
    if (!/^\s*##\s+\[/m.test(text)) return null; // only a new entry is judged, not a later touch of an old one
    if (!(FIX.test(text) || faultArrow(text)) || MARK.test(text)) return null;
    return blocked(root, policy, "02-91", "a new changelog entry in " + e.rel + " reports a fix but names no lesson: add L-<n> to the " +
      "lessons ledger (Cons_Gate_17_LessonsLedger) and name it in the entry, or write \"không có bài học: <lý do>\" when new code " +
      "cannot bring the fault back (a one-off data fault, an outside outage).");
  } catch { return null; }
}
module.exports = { check };
